import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.PriorityQueue;

public class Main {

    static class Edge {
        int to;
        int weight;
        int id;

        Edge(int to, int weight, int id) {
            this.to = to;
            this.weight = weight;
            this.id = id;
        }
    }

    static class Cycle {
        int id;
        long length;

        Cycle(int id, long length) {
            this.id = id;
            this.length = length;
        }
    }

    static int E, R;
    static ArrayList<Edge>[] adj;
    static int[] cycleId;
    static ArrayList<Cycle> cycles = new ArrayList<>();

    // DFS para detecção de ciclos
    static int[] depth;
    static int[] parentNode;
    static int[] parentWeight;
    static int[] parentEdgeId;
    static boolean[] visited;

    static void findCycles(int u, int p, int edgeId, int d) {
        visited[u] = true;
        depth[u] = d;

        for (Edge e : adj[u]) {
            if (e.id == edgeId) continue;
            int v = e.to;
            if (visited[v]) {
                if (depth[v] < depth[u]) {
                    // Back-edge encontrada: ciclo de v até u
                    int cId = cycles.size();
                    long cLen = e.weight;
                    int curr = u;
                    while (curr != v) {
                        cycleId[curr] = cId;
                        cLen += parentWeight[curr];
                        curr = parentNode[curr];
                    }
                    cycleId[v] = cId;
                    cycles.add(new Cycle(cId, cLen));
                }
            } else {
                parentNode[v] = u;
                parentWeight[v] = e.weight;
                parentEdgeId[v] = e.id;
                findCycles(v, u, e.id, d + 1);
            }
        }
    }

    static class NodeDist implements Comparable<NodeDist> {
        int u;
        long dist;

        NodeDist(int u, long dist) {
            this.u = u;
            this.dist = dist;
        }

        @Override
        public int compareTo(NodeDist o) {
            return Long.compare(this.dist, o.dist);
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        E = scanner.nextInt();
        R = scanner.nextInt();

        adj = new ArrayList[E + 1];
        for (int i = 1; i <= E; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < R; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            int c = scanner.nextInt();
            adj[u].add(new Edge(v, c, i));
            adj[v].add(new Edge(u, c, i));
        }

        cycleId = new int[E + 1];
        Arrays.fill(cycleId, -1);

        depth = new int[E + 1];
        parentNode = new int[E + 1];
        parentWeight = new int[E + 1];
        parentEdgeId = new int[E + 1];
        visited = new boolean[E + 1];

        for (int i = 1; i <= E; i++) {
            if (!visited[i]) {
                findCycles(i, 0, -1, 0);
            }
        }

        int K = scanner.nextInt();
        long[] dist = new long[E + 1];
        long[] minCycleDist = new long[cycles.size()];

        for (int q = 0; q < K; q++) {
            int X = scanner.nextInt();
            long T = scanner.nextLong();

            Arrays.fill(dist, Long.MAX_VALUE);
            PriorityQueue<NodeDist> pq = new PriorityQueue<>();

            dist[X] = 0;
            pq.add(new NodeDist(X, 0));

            while (!pq.isEmpty()) {
                NodeDist top = pq.poll();
                int u = top.u;
                long d = top.dist;

                if (d > dist[u]) continue;

                for (Edge e : adj[u]) {
                    if (dist[e.to] > d + e.weight) {
                        dist[e.to] = d + e.weight;
                        pq.add(new NodeDist(e.to, dist[e.to]));
                    }
                }
            }

            Arrays.fill(minCycleDist, Long.MAX_VALUE);
            for (int i = 1; i <= E; i++) {
                if (cycleId[i] != -1 && dist[i] != Long.MAX_VALUE) {
                    int cId = cycleId[i];
                    if (dist[i] < minCycleDist[cId]) {
                        minCycleDist[cId] = dist[i];
                    }
                }
            }

            long ans = Long.MAX_VALUE;
            for (Cycle c : cycles) {
                if (c.length >= T && minCycleDist[c.id] != Long.MAX_VALUE) {
                    long cost = 2 * minCycleDist[c.id] + c.length;
                    if (cost < ans) {
                        ans = cost;
                    }
                }
            }

            if (ans == Long.MAX_VALUE) {
                out.println(-1);
            } else {
                out.println(ans);
            }
        }

        out.flush();
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            byte b = read();
            while (b <= ' ' && b != -1) b = read();
            if (b == -1) return -1;
            boolean neg = false;
            if (b == '-') {
                neg = true;
                b = read();
            }
            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = read();
            }
            return neg ? -res : res;
        }

        public long nextLong() throws IOException {
            byte b = read();
            while (b <= ' ' && b != -1) b = read();
            if (b == -1) return -1;
            boolean neg = false;
            if (b == '-') {
                neg = true;
                b = read();
            }
            long res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = read();
            }
            return neg ? -res : res;
        }
    }
